[McpServerToolType]
public class PlcReadTools
{
    private const string ToolName = "plc_read";

    [McpServerTool(
        Name = ToolName,
        ReadOnly = true,
        Destructive = false,
        OpenWorld = false,
        UseStructuredContent = true,
        OutputSchemaType = typeof(OperationBatchReadResponse))]
    [Description("Run up to 50 PLC read operations in one call. Valid operations: get_block_content (blockPath, optional format xml|source|sd and withDependencies; sd returns only the SIMATIC SD documents of PlcBlock.ExportAsDocuments (.s7dcl, and .s7res when exported) delimited like the xml bundle, with an sd:sha256 contentHash and failSafe true when the .s7dcl header declares S7_Safety := \"TRUE\"; whatever TIA Portal refuses to export fails with its error; xml returns the SimaticML .xml plus the SD documents, and when TIA Portal exports no SimaticML (it does not export inconsistent blocks, e.g. one not compiled since it was created; confirmed live on V21 2026-11-02) the result holds the SD documents only and a warning says so: run compile_check and read again; live-tested on V21 2026-11-02: a block without texts exports only the .s7dcl), list_networks (blockPath; from the sd export: blockKind, blockName, preferredLanguage, failSafe, every header pragma (S7_PreferredLanguage, S7_Safety, ...), and per network its 1-based number in document order, language (S7_Language pragma, else detected from the RUNG syntax as the Siemens V21 simatic-sd skill does: languageSource pragma|detected, null when ambiguous), every pragma entry, titleId/title and commentId/comment resolved from the .s7res (S7_NetworkTitle, S7_NetworkComment ids, one text per culture), the body (code, common indentation removed) and exportOnlyForms (instruction forms the V21 export writes that are reported not to re-import; not reproduced live 2026-11-02 for GT/EQ_Contact, Move, P_Trig/N_Trig, TON/TOF, Add); contentHash is the sd hash for insert_network, replace_network and delete_network; live-tested on V21 2026-11-02), get_type_content (typePath, optional format and withDependencies), list_tag_tables (optional plcName, omitted reads every PLC; optional tableName and folderPath narrow to one table or one tag-table folder), list_download_targets (optional plcName, omitted reads every PLC; the offline download path for plc_download: connection modes, PC interfaces { name, number } and target interfaces, read from the project without going online or scanning the network), get_plc_security (optional plcName, omitted reads every PLC; CPU protection per CPU for diagnosing download and hardware compile errors: accessLevel (PlcAccessLevelProvider.PlcProtectionAccessLevel; readable false with a note when no password is configured, as Siemens documents), accessControl (PlcAccessControlConfigurationProvider.Configuration), confidentialDataProtection (PlcMasterSecretConfigurator: protectBindable, unprotectBindable, unprotectCandidates and the service's readable properties uninterpreted, because no documented member reports the checkbox state) and the CPU's service type names; every member is bound at runtime, not live-tested; never reads or handles a password), read_address_occupancy (assignment list of one PLC: declared I/Q/M tags plus, unless includeHardware is false, the PLC's hardware I/O addresses; optional plcName, areas; a tag's width is its data type's documented length, cross-checked with the address spelling; reports tag overlaps, I/Q tags outside hardware ranges, widthMismatches, tags without an absolute address and unsizedTags whose data type has no documented length, which make isComplete false), find_free_address (area I|Q|M and dataType; optional plcName, startByte and endByte 0..65535, alignBytes, requireHardware; the lowest address not used by any declared tag; isComplete is false when the inventory is incomplete or an unsized tag lies in the area), get_online_state (optional plcName; OnlineProvider.State, IsConfigured and the offline online path for plc_tia_online), list_station_upload_interfaces (the offline modes and PC interfaces for plc_station_upload), compare_software (compareTarget plc|project_library|master_copy|secondary_plc, targetName for plc, master_copy and secondary_plc, targetProject for secondary_plc (the path of an open secondary project, library_write open_secondary_project; issue #20, not live-tested), optional plcName, maxDepth, maxElements, differencesOnly; PlcSoftware.CompareTo, offline), compare_to_online (optional plcName, maxDepth, maxElements, differencesOnly, trustedCertificates, passwords { OnlineReadAccessPassword: source, ... } (password sources, never values; omitted entries come from the server password map); PlcSoftware.CompareToOnline: connects to the PLC with the path TIA Portal has configured but changes nothing; a connection the compare opened is closed again; allowed in every mode), compare_hardware and compare_hardware_to_online (issue #7, not live-tested; HardwareObject.CompareTo(IHardwareCompareTarget) of the PLC's station (hardwareScope device, default) or CPU device item (cpu): compare_hardware takes compareTarget plc (the other PLC's object of the same scope, targetName) or master_copy (a root master copy of the project library, targetName), compare_hardware_to_online the CPU's OnlineProvider as the target with optional trustedCertificates and passwords under exactly the rules of compare_to_online (connection closed again, TLS trusted only from trustedCertificates, allowed in every mode); V21 does not document which types implement IHardwareCompareTarget, so a target that does not implement it at runtime is unsupported_capability before anything is compared or contacted; same bounded tree and caps), list_watch_and_force_tables (optional plcName), read_watch_table and read_force_table (tableName, optional plcName, folderPath group path and maxElements; entries read attribute by attribute), get_watch_table_content and get_force_table_content (tableName, optional plcName and folderPath; SimaticML with contentHash for update_watch_table_content/update_force_table_content), get_block_interface (blockPath: block identity with number, language and know-how protection, the xml contentHash and the interface sections as a member tree with data types, start values, comments and exported